"""Convert a GTRS vocabulary label pickle ({token: {metric: float16[V]}}, HF Zzxxxxxxxx/gtrs, generated by
navsim/agents/tools/gen_vocab_score.py with pdm_score_full_v2) into selector-pool shards readable by eval_bridge_selectors.load:
  tokens (N,), pdm (N,V,M) float16 with the metric names in metrics.json, plus the vocabulary copied as anchors.npy.
No model logits exist in this pool (logit0/logit1 absent): audits that need a selector skip it.
Peak RAM = size of the pickle (loaded once), so run the 8192 file (15 GB) before the 16384 one (30 GB) on a busy box.
  python test/selector/convert_gtrs_labels.py ori/navtrain_8192.pkl traj_final/8192.npy OUT_DIR [--shard 512]
"""
import argparse, json, pickle, shutil, time
from pathlib import Path
import numpy as np

ap = argparse.ArgumentParser()
ap.add_argument("pkl"); ap.add_argument("vocab_npy"); ap.add_argument("out")
ap.add_argument("--shard", type=int, default=512)
a = ap.parse_args()
out = Path(a.out); out.mkdir(parents=True, exist_ok=True)
t0 = time.time()
with open(a.pkl, "rb") as f:
    d = pickle.load(f)
print(f"loaded {len(d)} scenes in {time.time() - t0:.0f}s")
tokens = sorted(d)
metrics = sorted(d[tokens[0]].keys())
V = len(d[tokens[0]][metrics[0]])
(out / "metrics.json").write_text(json.dumps({"columns": metrics, "V": V, "source": str(a.pkl), "note": "NAVSIM v2 components (pdm_score_full_v2), human-reference forgiveness applied by the generator"}))
shutil.copy(a.vocab_npy, out / "anchors.npy")
for si, s in enumerate(range(0, len(tokens), a.shard)):
    tk = tokens[s:s + a.shard]
    pdm = np.stack([np.stack([np.asarray(d[t][m], dtype=np.float16) for m in metrics], axis=-1) for t in tk])  # (n,V,M)
    np.savez(out / f"shard_{si:04d}.npz", tokens=np.array(tk), pdm=pdm)
    for t in tk:
        del d[t]
    if si % 20 == 0:
        print(f"shard {si}: {s + len(tk)}/{len(tokens)} scenes, {time.time() - t0:.0f}s", flush=True)
print("done", out)
